def occurrences(start, freq, interval, count, until, byweekday, exdates):
    from datetime import datetime, timedelta

    start_date = datetime.strptime(start, '%Y-%m-%d').date()
    exdates_set = set(exdates) if exdates else set()

    candidates = []

    if freq == 'daily':
        k = 0
        while True:
            candidate = start_date + timedelta(days=k * interval)

            if until and candidate > datetime.strptime(until, '%Y-%m-%d').date():
                break
            if count is not None and len(candidates) >= count:
                break

            candidates.append(candidate)
            k += 1

    elif freq == 'weekly':
        start_weekday = start_date.weekday()
        target_weekdays = byweekday if byweekday is not None else [start_weekday]
        target_weekdays_set = set(target_weekdays)

        start_week_monday = start_date - timedelta(days=start_weekday)

        week_num = 0
        while True:
            if week_num % interval == 0:
                week_monday = start_week_monday + timedelta(weeks=week_num)

                for day_offset in range(7):
                    candidate = week_monday + timedelta(days=day_offset)

                    if candidate < start_date:
                        continue
                    if until and candidate > datetime.strptime(until, '%Y-%m-%d').date():
                        break
                    if count is not None and len(candidates) >= count:
                        break

                    if candidate.weekday() in target_weekdays_set:
                        candidates.append(candidate)

                if count is not None and len(candidates) >= count:
                    break
                if until and week_monday + timedelta(days=6) > datetime.strptime(until, '%Y-%m-%d').date():
                    break

            week_num += 1
            if week_num > 10000:
                break

    elif freq == 'monthly':
        target_day = start_date.day
        year = start_date.year
        month = start_date.month

        month_num = 0
        while True:
            year_offset = (month - 1 + month_num * interval) // 12
            month_offset = (month - 1 + month_num * interval) % 12

            candidate_year = year + year_offset
            candidate_month = month_offset + 1

            try:
                candidate = datetime(candidate_year, candidate_month, target_day).date()
            except ValueError:
                month_num += 1
                continue

            if until and candidate > datetime.strptime(until, '%Y-%m-%d').date():
                break
            if count is not None and len(candidates) >= count:
                break

            candidates.append(candidate)
            month_num += 1

            if month_num > 10000:
                break

    result = [c.strftime('%Y-%m-%d') for c in candidates if c.strftime('%Y-%m-%d') not in exdates_set]
    return sorted(result)

